INSERT INTO public.video_clips (path, prompt, short_prompt, labels, image_1_caption, image_2_caption, image_3_caption, resolution, aspect_ratio, fps, duration) VALUES ('96.mp4', 'Nature: lake, trees, mist, mountains, cliffs. Objects: sphere. Scenes: fantasy, landscape, fantasy landscape, surreal. Emotions: serene, mystical, mysterious. Concepts: surrealism, contrast, otherworldly, ethereal', 'Nature: lake, trees, mist, mountains, cliffs. Objects: sphere. Scenes: fantasy, landscape, fantasy l...', 'lake, trees, mist, mountains, cliffs, sphere, fantasy, landscape, fantasy landscape, surreal, serene, mystical, mysterious, surrealism, contrast, otherworldly, ethereal', 'A colossal, glowing sphere hovers above a tranquil lake surrounded by lush greenery and misty mountains. The sphere emits a fiery glow, contrasting with the serene natural landscape. The scene is enveloped in a mystical atmosphere, blending elements of fantasy and nature.', 'A massive, otherworldly sphere hovers above a serene lake, emitting a mysterious glow. Mist rises from the water, creating an ethereal atmosphere as the sphere''s surface shimmers with fiery patterns. Tall trees and rocky cliffs frame the scene, enhancing the surreal landscape.', NULL, '1248x1632', '13:17', 30.0, '5s');
