INSERT INTO public.video_clips (path, prompt, short_prompt, labels, image_1_caption, image_2_caption, image_3_caption, resolution, aspect_ratio, fps, duration) VALUES ('98.mp4', 'Animals: bird, chicks. Nature: leaves, nest, raindrops. Objects: nest. Actions: sheltering, feeding, nurturing, protecting, perching. Emotions: protective, nurturing, caring, care. Scenes: wildlife, nature, natural habitat, rainy. Concepts: parenting, nature, care, parenthood, protection', 'Animals: bird, chicks. Nature: leaves, nest, raindrops. Objects: nest. Actions: sheltering, feeding,...', 'bird, chicks, leaves, nest, raindrops, nest, sheltering, feeding, nurturing, protecting, perching, protective, nurturing, caring, care, wildlife, nature, natural habitat, rainy, parenting, nature, care, parenthood, protection', 'A small bird with yellow and brown plumage is perched protectively over its nest, sheltering its chicks. The nest is intricately woven and nestled among green leaves, with raindrops visible in the background. The scene captures a moment of nurturing and care in a natural setting.', 'A vibrant yellow bird with outstretched wings stands protectively over its nest, which contains two hungry chicks with open beaks. The nest is intricately woven and nestled among lush green leaves, creating a serene natural setting.', 'A small bird with olive-green plumage is perched on a nest, sheltering its two chicks. The chicks, with their beaks wide open, eagerly await feeding. The scene is set against a backdrop of lush green leaves, with raindrops visible in the air.', '1080x1920', '9:16', 30.0, '10s');
